statement:
Treat the integer array `nums` as circular: one step right from the last index reaches index `0`, and one step left from index `0` reaches the last index.

Return a new array `result` of the same length in which each `result[i]` is found on its own, from the original `nums`:

- if `nums[i] > 0`, walk `nums[i]` steps to the right starting from index `i`;
- if `nums[i] < 0`, walk `|nums[i]|` steps to the left starting from index `i`;
- in both cases `result[i]` is the value of `nums` at the index where the walk ends;
- if `nums[i] == 0`, `result[i]` is `nums[i]` (that is, `0`).

validator:
function validate([nums]) {
  if (nums.length < 1 || nums.length > 100) return 'nums needs 1 to 100 values.';
  if (nums.some(v => v < -100 || v > 100)) return 'Each value is between -100 and 100.';
  return null;
}

reference:
function constructTransformedArray(nums) {
  const n = nums.length;
  const result = new Array(n);
  for (let i = 0; i < n; i++) {
    const landing = (((i + nums[i]) % n) + n) % n;
    result[i] = nums[landing];
  }
  return result;
}

