function constructTransformedArray(nums) {
  const n = nums.length;
  // Walk one step at a time, wrapping by hand at both ends.
  return nums.map((value, i) => {
    let position = i;
    for (let moved = 0; moved < Math.abs(value); moved++) {
      position += value > 0 ? 1 : -1;
      if (position === n) position = 0;
      if (position === -1) position = n - 1;
    }
    return nums[position];
  });
}

generator:
function generate(rand, size) {
  const pick = n => Math.floor(rand() * n);
  const n = size === 'large' ? 90 + pick(11) : 1 + pick(8);
  // Small spans keep walks short; a span of 100 wraps around a short array many times.
  const span = size === 'large' ? 100 : [3, 12, 100][pick(3)];
  const nums = Array.from({ length: n }, () => (rand() < 0.15 ? 0 : pick(2 * span + 1) - span));
  return [nums];
}
